 private void voidDialog(PagoProveedorDto x,Dialog parent){Dialog d=dialog("ANULAR PAGO");TextArea reason=new TextArea("Motivo de anulación");reason.setRequiredIndicatorVisible(true);d.add(reason);d.getFooter().add(new AppActionButton(ActionType.VOID,ButtonSize.MAIN,"Anular",e->{try{service.voidPayment(x.id(),x.version(),reason.getValue());d.close();parent.close();load();Notification.show("Pago anulado correctamente.");}catch(RuntimeException ex){error(ex,"No fue posible anular el pago.");}}),new AppActionButton(ActionType.CANCEL,ButtonSize.MAIN,"Cancelar",e->d.close()));d.open();}

 private static PagoProveedorInput input(ComboBox<PagoProveedorCatalogosDto.Opcion>s,DatePicker d,ComboBox<PagoProveedorCatalogosDto.Opcion>c,BigDecimalField a,Select<MedioPagoMovimiento>m,ComboBox<CuentaDineroOpcionDto>source,TextField check,TextField ref,TextArea notes,Map<UUID,BigDecimal>alloc,PagoProveedorDto current,UUID formKey){TipoCuentaDinero type=type(m.getValue());return new PagoProveedorInput(id(s),d.getValue(),id(c),a.getValue(),m.getValue(),type,source.getValue()==null?null:source.getValue().id(),check.getValue(),ref.getValue(),notes.getValue(),alloc.entrySet().stream().filter(x->x.getValue()!=null&&x.getValue().signum()>0).map(x->new PagoProveedorInput.Aplicacion(x.getKey(),x.getValue())).toList(),current==null?null:current.version(),formKey);}
 private static TipoCuentaDinero type(MedioPagoMovimiento m){return m==null?null:m==MedioPagoMovimiento.CASH?TipoCuentaDinero.CASH_REGISTER:TipoCuentaDinero.BANK_ACCOUNT;}private static <T extends PagoProveedorCatalogosDto.Opcion>ComboBox<T> combo(String label,List<T>items){ComboBox<T>c=new ComboBox<>(label);c.setItems(items);c.setItemLabelGenerator(PagoProveedorCatalogosDto.Opcion::nombre);c.setClearButtonVisible(true);return c;}private static void select(ComboBox<PagoProveedorCatalogosDto.Opcion>c,List<PagoProveedorCatalogosDto.Opcion>xs,UUID id){c.setValue(xs.stream().filter(x->Objects.equals(x.id(),id)).findFirst().orElse(null));}private static UUID id(ComboBox<PagoProveedorCatalogosDto.Opcion>c){return c.getValue()==null?null:c.getValue().id();}private static Div section(String title,Component...fields){Div d=new Div();d.addClassName("cc-form-section");d.add(new H3(title));Div f=new Div(fields);f.addClassName("cc-dialog-form");d.add(f);return d;}private static Dialog dialog(String title){Dialog d=new Dialog();d.setHeaderTitle(title);d.setWidth("min(1180px,96vw)");d.setHeight("min(920px,96vh)");return d;}private static HorizontalLayout row(String name,Component value){HorizontalLayout r=new HorizontalLayout(new Span(name),value);r.setWidthFull();r.setJustifyContentMode(JustifyContentMode.BETWEEN);return r;}private static HorizontalLayout actions(){HorizontalLayout h=new HorizontalLayout();h.addClassName("cc-grid-actions");h.setSpacing(false);return h;}private static Span badge(EstadoPagoProveedor s){Span x=new Span(state(s));x.getElement().getThemeList().add("badge "+(s==EstadoPagoProveedor.APPLIED?"success":s==EstadoPagoProveedor.VOIDED?"error":s==EstadoPagoProveedor.DRAFT?"contrast":"primary"));return x;}private static String state(EstadoPagoProveedor s){if(s==null)return "Todos";return switch(s){case DRAFT->"Borrador";case AVAILABLE->"Disponible";case PARTIALLY_APPLIED->"Parcialmente aplicado";case APPLIED->"Aplicado";case VOIDED->"Anulado";};}private static BigDecimal total(Map<UUID,BigDecimal>m){return m.values().stream().filter(Objects::nonNull).reduce(BigDecimal.ZERO,BigDecimal::add);}private static BigDecimal nz(BigDecimal v){return v==null?BigDecimal.ZERO:v;}private static String money(BigDecimal v){return v==null?"—":String.format(Locale.US,"%,.2f",v);}private static String value(String v){return v==null?"":v;}private static boolean can(String p){return TenantContext.principalActual().permisos().contains(p);}private static void error(RuntimeException e,String fallback){Throwable cause=e;while(cause.getCause()!=null&&cause!=cause.getCause())cause=cause.getCause();String message=cause instanceof ReglaNegocioException||cause instanceof RecursoNoEncontradoException?cause.getMessage():fallback;if(message==null||message.isBlank())message=fallback;if(message.equals(fallback))LOG.error(fallback,e);else LOG.warn("{}: {}",fallback,message);Notification.show(message);}
